<include file="Publics:header"/>	<div class="mainbox">		<if condition="$yingshan">			<div>				<div style="display: inline-block;margin-right: 10px">圆角半径:</div>				<div id="slideTest1" style="width: 100px;display: inline-block"></div>				<div style="display: inline-block;margin-left: 15px">					<input type="number" class="input fl" id="fillet_radius" style="width: 50px;margin-right: 20px" name="fillet_radius" min="0" max="50" size="20" value="{pigcms{$fillet_radius}"/>					<span onclick="saveFilletRadius()" style="line-height: 30px;display: inline-block;background-color: #3283FA;color:#FFFFFF;padding: 0 10px;border-radius: 5px;cursor: pointer">								保存							</span>					<span>圆角半径默认为0,最大设置为50,圆角半径值越大，圆角越圆，0是为直角。</span>				</div>			</div>		</if>        <if condition="$chooseSize">            <div style="margin-top: 10px;">                <div style="display: inline-block;margin-right: 10px">{pigcms{$chooseSizeTitle}:</div>                <div style="display: inline-block;">                    <select class="" name="size_info" id="size_info" style="width:150px;">                        <option value="" style="display: none;">请选择{pigcms{$chooseSizeTitle}</option>                        <volist name='chooseSize' id='sizeVal'>                            <option <if condition="$size_info eq $sizeVal['value']">selected="selected"</if> value="{pigcms{$sizeVal.value}">{pigcms{$sizeVal.label}</option>                        </volist>                    </select>                    <span onclick="saveAdvertSize()" style="line-height: 30px;display: inline-block;background-color: #3283FA;color:#FFFFFF;padding: 0 10px;border-radius: 5px;cursor: pointer"> 保存 </span>                    <span>上传的广告图，按照设置的尺寸进行显示。</span>                </div>            </div>        </if>		<div id="nav" class="mainnav_title">			<ul>				<if condition="empty($_GET['frame_show'])">					<a href="{pigcms{:U('Adver/index')}">广告分类列表</a>|				</if>				<a href="{pigcms{:U('Adver/adver_list',$_GET)}" class="on">{pigcms{$now_category.cat_name} - 列表</a>|                <if condition="$assign_type"><a href="javascript:void(0);" onclick="window.top.artiframe('{pigcms{:U('Adver/adver_add',array('cat_id'=>$now_category['cat_id'],'from_page'=>$_GET['from_page']))}','添加广告',850,580,true,false,false,addbtn,'add',true);"><if condition="$_GET['cat_key'] eq 'house_app_index_top'">添加轮播<else/>添加广告</if></a></if>			</ul>		</div>		<div class="page_tips">广告建议尺寸：{pigcms{:str_replace(' ','&nbsp;',$now_category['size_info'])}&nbsp;&nbsp;平台已为你添加<span>{pigcms{$adver_count}</span> 张。<if condition="$_GET['cat_key'] neq 'house_four_adver'"><div >添加的广告图，用户端只展示最新上传的{pigcms{$cat_key_num}张广告图进行轮播。</div></if></div>		<form name="myform" id="myform" action="" method="post">			<div class="table-list">				<table width="100%" cellspacing="0">					<thead>						<tr>							<th>编号</th>							<th>名称</th>							<th>链接地址</th>							<th>图片(以下为强制小图，点击图片查看大图)</th>							<th class="textcenter">最后操作时间</th>							<th style="width: 60px">状态</th>                            <if condition="$assign_type ">							<th class="textcenter">操作</th>                            </if>						</tr>					</thead>					<tbody>						<if condition="is_array($adver_list)">							<volist name="adver_list" id="vo">								<tr>									<td>{pigcms{$vo.id}</td>									<td>{pigcms{$vo.name}</td>									<td><a href="{pigcms{$vo.url}" target="_blank">访问链接</a></td>									<td>										<img src="{pigcms{:file_domain()}{pigcms{$vo.pic}" style="width:32px;height:32px;" class="view_msg"/>									</td>									<td class="textcenter">{pigcms{$vo.last_time|date='Y-m-d H:i:s',###}</td>									<td>                                        <if condition="$vo['status'] eq 1">                                            <font color="green">正常</font>                                        <elseif condition="$vo['status'] eq 0"/>                                            <font color="red">关闭</font>                                        </if>                                    </td>                                    <if condition="$assign_type">                                        <td class="textcenter">                                            <a href="javascript:void(0);" onclick="window.top.artiframe('{pigcms{:U('Adver/adver_edit',array('id'=>$vo['id'],'from_page'=>$_GET['from_page']))}','编辑广告信息',850,580,true,false,false,editbtn,'add',true);">编辑</a> | <a href="javascript:void(0);" class="delete_row" parameter="id={pigcms{$vo.id}" url="{pigcms{:U('Adver/adver_del')}">删除</a>                                        </td>                                    </if>								</tr>							</volist>						<else/>							<tr><td class="textcenter red" <if condition="$assign_type "> colspan="6" <else/>colspan="7"</if> >列表为空！</td></tr>						</if>					</tbody>				</table>			</div>		</form>	</div><link rel="stylesheet" href="{pigcms{$static_public}layui2/css/layui.css" media="all"/><script src="{pigcms{$static_public}layui2/layui.all.js" charset="utf-8"></script><script>  layui.use('slider', function(){    var slider = layui.slider;    //渲染    var ins1 = slider.render({      elem: '#slideTest1',  //绑定元素      min: 0,      max: 50,      change: function(value){        $("#fillet_radius").val(value)      }    });    $(function (){      ins1.setValue($("#fillet_radius").val())    })    $("#fillet_radius").on('keyup',function (e){      ins1.setValue(e.delegateTarget.value)    })  });    function saveAdvertSize() {      var size_info = $("#size_info").val()      layer.confirm("是否保存{pigcms{$chooseSizeTitle}吗?",{          btn: ['确认', '取消']      }, function () {          var url ="{pigcms{:U('Adver/setAdvertSize')}";          var cat_key = "{pigcms{$_GET['cat_key']}"          $.post(url,{'size_info': size_info, 'cat_key': cat_key},function(data){              layer.msg(data['msg'])          },'json')      });  }  function saveFilletRadius() {      var fillet_radius = $("#fillet_radius").val()      layer.confirm("是否保存圆角参数吗?", {          btn: ['确认', '取消']      }, function () {          var url = "{pigcms{:U('Library/set_village_nav')}";          $.post(url, {'fillet_radius': fillet_radius,}, function (data) {              layer.msg(data['msg'])          }, 'json')      });  }</script><include file="Publics:footer"/>